<?php
namespace Modules\BankingCheque\Http\Controllers;
use Illuminate\Routing\Controller; use Illuminate\Http\Request; use Modules\BankingCheque\Entities\ChequeClearingItem;
class ReturnedChequeController extends Controller { public function index(){ $items=ChequeClearingItem::where('status','returned')->latest()->paginate(25); return view('bankingcheque::returns.index',compact('items')); } public function create(){ return view('bankingcheque::returns.create'); } public function store(Request $r){ ChequeClearingItem::create($r->all()+['status'=>'returned']); return redirect()->route('banking.cheques.returned-cheques.index'); } public function show(ChequeClearingItem $returned_cheque){ return view('bankingcheque::returns.show',['item'=>$returned_cheque]); } public function edit(ChequeClearingItem $returned_cheque){ return view('bankingcheque::returns.edit',['item'=>$returned_cheque]); } public function update(Request $r, ChequeClearingItem $returned_cheque){ $returned_cheque->update($r->all()); return back(); } public function destroy(ChequeClearingItem $returned_cheque){ $returned_cheque->delete(); return back(); } }
